<?php
require_once '../config/db.php';
require_once '../includes/language.php';
if(session_status()===PHP_SESSION_NONE)session_start();
if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}
$user_id=(int)$_SESSION['user_id']; if(empty($_SESSION['chat_csrf']))$_SESSION['chat_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['chat_csrf'];
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function localized_number($v){$v=(string)$v;return (($GLOBALS['current_language']??'bn')==='bn')?strtr($v,['0'=>'০','1'=>'১','2'=>'২','3'=>'৩','4'=>'৪','5'=>'৫','6'=>'৬','7'=>'৭','8'=>'৮','9'=>'৯']):$v;}
function localized_chat_date($value){$ts=strtotime($value);if(!$ts)return (string)$value;$out=date('d M Y, h:i A',$ts);if(($GLOBALS['current_language']??'bn')==='en')return $out;$months=['Jan'=>'জানু','Feb'=>'ফেব্রু','Mar'=>'মার্চ','Apr'=>'এপ্রি','May'=>'মে','Jun'=>'জুন','Jul'=>'জুল','Aug'=>'আগ','Sep'=>'সেপ্টে','Oct'=>'অক্টো','Nov'=>'নভে','Dec'=>'ডিসে'];$out=strtr($out,$months);$out=strtr($out,['AM'=>'পূর্বাহ্ণ','PM'=>'অপরাহ্ণ']);return localized_number($out);}

$conversation_id=(int)($_GET['conversation_id']??0); if($conversation_id<=0){header('Location: messages.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf_token']??''))){header('Location: conversation.php?conversation_id='.$conversation_id.'&message='.urlencode(sm_text('Security check failed.','নিরাপত্তা যাচাই ব্যর্থ হয়েছে।')));exit;}
 $message=trim((string)($_POST['message']??''));
 if($message===''){header('Location: conversation.php?conversation_id='.$conversation_id.'&message='.urlencode(sm_text('Please write a message.','অনুগ্রহ করে একটি বার্তা লিখুন।')));exit;}
 if(mb_strlen($message)>1000)$message=mb_substr($message,0,1000);
 $st=mysqli_prepare($conn,"SELECT c.*,cr.status AS request_status,cr.chat_active,cr.sender_user_id AS req_sender,cr.receiver_user_id AS req_receiver FROM conversations c JOIN chat_requests cr ON cr.chat_request_id=c.chat_request_id WHERE c.conversation_id=? AND (c.user1_id=? OR c.user2_id=?) LIMIT 1");mysqli_stmt_bind_param($st,'iii',$conversation_id,$user_id,$user_id);mysqli_stmt_execute($st);$conv=mysqli_fetch_assoc(mysqli_stmt_get_result($st));mysqli_stmt_close($st);
 if(!$conv||$conv['status']!=='Active'||$conv['request_status']!=='Accepted'||(int)$conv['chat_active']!==1){header('Location: messages.php?message='.urlencode(sm_text('This conversation is no longer active.','এই কথোপকথনটি আর সক্রিয় নেই।')));exit;}
 $count=(int)($conv['user1_id']==$user_id?$conv['user1_message_count']:$conv['user2_message_count']);$limit=(int)$conv['message_limit'];
 if($count >= $limit){header('Location: conversation.php?conversation_id='.$conversation_id.'&message='.urlencode(sm_text('Your message limit for this conversation has been reached.','এই কথোপকথনে আপনার বার্তা পাঠানোর সীমা পূর্ণ হয়েছে।')));exit;}
 mysqli_begin_transaction($conn);try{$st=mysqli_prepare($conn,"INSERT INTO conversation_messages(conversation_id,sender_user_id,message) VALUES(?,?,?)");mysqli_stmt_bind_param($st,'iis',$conversation_id,$user_id,$message);if(!mysqli_stmt_execute($st))throw new Exception();mysqli_stmt_close($st);if((int)$conv['user1_id']===$user_id)$sql="UPDATE conversations SET user1_message_count=user1_message_count+1 WHERE conversation_id=?";else$sql="UPDATE conversations SET user2_message_count=user2_message_count+1 WHERE conversation_id=?";$st=mysqli_prepare($conn,$sql);mysqli_stmt_bind_param($st,'i',$conversation_id);if(!mysqli_stmt_execute($st))throw new Exception();mysqli_stmt_close($st);mysqli_commit($conn);}catch(Throwable $e){mysqli_rollback($conn);header('Location: conversation.php?conversation_id='.$conversation_id.'&message='.urlencode(sm_text('Unable to send message right now.','এই মুহূর্তে বার্তা পাঠানো যাচ্ছে না।')));exit;}header('Location: conversation.php?conversation_id='.$conversation_id);exit;
}
$st=mysqli_prepare($conn,"SELECT c.*,cr.status AS request_status,cr.chat_active,CONCAT(u.first_name,' ',u.last_name) AS other_name,u.user_id AS other_id,up.photo,up.photo_visibility FROM conversations c JOIN chat_requests cr ON cr.chat_request_id=c.chat_request_id JOIN users u ON u.user_id=CASE WHEN c.user1_id=? THEN c.user2_id ELSE c.user1_id END LEFT JOIN user_profiles up ON up.user_id=u.user_id WHERE c.conversation_id=? AND (c.user1_id=? OR c.user2_id=?) LIMIT 1");mysqli_stmt_bind_param($st,'iiii',$user_id,$conversation_id,$user_id,$user_id);mysqli_stmt_execute($st);$conv=mysqli_fetch_assoc(mysqli_stmt_get_result($st));mysqli_stmt_close($st);if(!$conv){header('Location: messages.php?message='.urlencode(sm_text('Conversation not found.','কথোপকথনটি পাওয়া যায়নি.')));exit;}
$st=mysqli_prepare($conn,"SELECT cm.*,CONCAT(u.first_name,' ',u.last_name) sender_name FROM conversation_messages cm JOIN users u ON u.user_id=cm.sender_user_id WHERE cm.conversation_id=? ORDER BY cm.message_id ASC");mysqli_stmt_bind_param($st,'i',$conversation_id);mysqli_stmt_execute($st);$messages=[];$res=mysqli_stmt_get_result($st);while($m=mysqli_fetch_assoc($res))$messages[]=$m;mysqli_stmt_close($st);$flash=$_GET['message']??'';$mine=(int)$conv['user1_id']===$user_id?(int)$conv['user1_message_count']:(int)$conv['user2_message_count'];
$page_css = 'assets/css/messages.css';
include '../includes/header.php';include '../includes/navbar.php';
?><main class="chat-page matching-standalone-header"><div class="chat-wrap"><a class="chat-back" href="messages.php"><i class="fa-solid fa-arrow-left"></i> <?=sm_text('Messages','বার্তা')?></a><section class="conversation"><header class="conversation-head"><div class="chat-avatar small"><?php if(!empty($conv['photo'])):?><img src="<?=BASE_URL?>uploads/profile/<?=h($conv['photo'])?>" alt="<?=h(sm_text('Profile photo','প্রোফাইলের ছবি'))?>"><?php else:?><i class="fa-solid fa-user"></i><?php endif;?></div><div><span><?=sm_text('PRIVATE CONVERSATION','ব্যক্তিগত কথোপকথন')?></span><h1><?=h($conv['other_name'])?></h1><p><?=sm_text('Respectful communication','সম্মানজনক যোগাযোগ')?> • <?=h(localized_number($mine))?> / <?=h(localized_number($conv['message_limit']))?> <?=sm_text('messages used','টি বার্তা ব্যবহৃত')?></p></div><a href="../profile/view_profile.php?user_id=<?=h($conv['other_id'])?>" class="chat-secondary"><?=sm_text('View Profile','প্রোফাইল দেখুন')?></a></header><?php if($flash):?><div class="chat-alert info"><?=h($flash)?></div><?php endif;?><div class="message-list"><?php if(!$messages):?><div class="message-empty"><i class="fa-regular fa-message"></i><p><?=sm_text('No messages yet. Start with a respectful introduction.','এখনো কোনো বার্তা নেই। ভদ্রভাবে পরিচয় দিয়ে কথা শুরু করুন।')?></p></div><?php else:foreach($messages as $m):?><div class="bubble-row <?=$m['sender_user_id']==$user_id?'mine':'theirs'?>"><div class="bubble"><div><?=nl2br(h($m['message']))?></div><small><?=h(localized_chat_date($m['created_at']))?></small></div></div><?php endforeach;endif;?></div><?php if($conv['status']==='Active'&&$conv['request_status']==='Accepted'&&(int)$conv['chat_active']===1&&$mine<(int)$conv['message_limit']):?><form class="message-form" method="post"><input type="hidden" name="csrf_token" value="<?=h($csrf)?>"><textarea name="message" maxlength="1000" placeholder="<?=h(sm_text('Write a respectful message…','সম্মানজনক একটি বার্তা লিখুন…'))?>" required></textarea><button class="chat-primary"><?=sm_text('Send Message','বার্তা পাঠান')?> <i class="fa-solid fa-paper-plane"></i></button></form><?php elseif($mine>=(int)$conv['message_limit']):?><div class="limit-note"><?=sm_text('You have reached the message limit for this conversation.','এই কথোপকথনে বার্তা পাঠানোর সীমা পূর্ণ হয়েছে।')?> (<?=h(localized_number($conv['message_limit']))?>)</div><?php else:?><div class="limit-note"><?=sm_text('This conversation is closed.','এই কথোপকথনটি বন্ধ।')?></div><?php endif;?><form method="post" action="message_action.php" class="close-chat-form"><input type="hidden" name="csrf_token" value="<?=h($csrf)?>"><input type="hidden" name="chat_request_id" value="<?=h($conv['chat_request_id'])?>"><button name="action" value="close_chat" class="chat-danger"><?=sm_text('Close Conversation','কথোপকথন বন্ধ করুন')?></button></form></section></div></main>
<script src="../assets/js/messages-menu.js"></script><script>window.addEventListener('load',function(){const el=document.querySelector('.message-list');if(el)el.scrollTop=el.scrollHeight;});</script>
